/**
 * A restaurant menu by sections: a nav of section links, then each section (heading and note) with its dishes as
 * menu lines (name, a dotted leader, the price; the summary and weight below). No cart. Axes: cols (1, 2), tone.
 */
import { Fragment, type ReactNode } from "react";
import { Badge, Box, Inline, List, ListItem, Stack, Text, Title } from "../compose";
import { EmptyState } from "../components/empty-state";
import { MenuSectionNav } from "../components/menu-section-nav";
import { SectionFrame } from "../components/section-frame";
import { fmtMoney, tpl } from "../utils";
import type { DishSection } from "./restaurant-menu.types";
import type { Dish, FoodLabels } from "./dish-showcase.types";

export type RestaurantMenuProps = {
  id: string;
  title: string;
  lead?: string;
  dishes: Dish[];
  sections: DishSection[];
  empty?: string;
  labels: FoodLabels;
  cols?: "1" | "2";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function RestaurantMenu({
  id,
  title,
  lead = "",
  dishes,
  sections,
  empty = "",
  labels,
  cols = "1",
  tone = "default",
  landmarkLabel,
}: RestaurantMenuProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} landmarkLabel={landmarkLabel}>
      {((sections?.length ?? 0) === 0) ? (
        <EmptyState icon="star" title={empty} />
      ) : (
        <Stack gap="8" align="stretch" className={(((cols as string) === "1") ? "mx-auto w-full max-w-3xl" : "")}>
          <MenuSectionNav label={labels.sections} sections={sections} prefix={id} landmarkLabel={landmarkLabel} />
          <Box
            className={
              (cols as string) === "2" ? "grid grid-cols-1 gap-8 md:grid-cols-2"
              : "flex flex-col gap-8"
            }
            data-slot="items"
          >
            {(sections ?? []).map((s) => (
              <Stack key={s.id} gap="4" id={tpl("{0}-{1}", id, s.key)} data-slot="menusection">
                <Stack gap="0" className="border-b border-border pb-2">
                  <Title as={3} size="xl" weight="bold">
                    {s.title}
                  </Title>
                  <Text size="sm" className="text-muted-foreground">
                    {s.note}
                  </Text>
                </Stack>
                <List tag="ul" className="flex flex-col gap-4">
                  {(dishes ?? []).map((d) => (
                    <Fragment key={d.id}>
                      {(d.tag === s.key) ? (
                        <ListItem className="flex flex-col gap-0" data-slot="item">
                          <Box className="flex items-baseline gap-2">
                            <Inline className="font-semibold">
                              {d.name}
                            </Inline>
                            {d.badge ? (
                              <Badge variant="outline" size="sm">
                                {d.badge}
                              </Badge>
                            ) : null}
                            <Inline className="flex-1 border-b border-dotted border-border" aria-hidden="true" />
                            <Inline className="font-semibold">
                              {fmtMoney(d.price, d.currency)}
                            </Inline>
                          </Box>
                          <Text size="sm" className="text-muted-foreground">
                            {tpl("{0} · {1}", d.summary, d.weight)}
                          </Text>
                        </ListItem>
                      ) : null}
                    </Fragment>
                  ))}
                </List>
              </Stack>
            ))}
          </Box>
        </Stack>
      )}
    </SectionFrame>
  );
}

